import{_ as r,c as i,o as l,ah as o}from"./chunks/framework.Ch_PcVtW.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/output/PART3/4/0_context_summary.md","filePath":"scripts/output/PART3/4/0_context_summary.md"}'),s={name:"scripts/output/PART3/4/0_context_summary.md"};function a(n,t,e,_,c,g){return l(),i("div",null,[...t[0]||(t[0]=[o('<h2 id="_1-本篇主题与主要内容概述" tabindex="-1">1）本篇主题与主要内容概述 <a class="header-anchor" href="#_1-本篇主题与主要内容概述" aria-label="Permalink to &quot;1）本篇主题与主要内容概述&quot;">​</a></h2><p>本篇围绕BMSG于2024年2月发布的《不让音乐行业走向不可持续的提言》展开，重点讨论CD依赖型商业模式造成的重复购买、塑料浪费、流媒体发展滞后及日本音乐市场竞争力下降等问题。SKY-HI主张通过减少CD包装塑料、削减随机及店铺限定特典、将CD与周边商品需求分离等方式推进改革。同时，他强调并非否定唱片公司的价值，而是希望唱片公司、艺人、销售渠道及行业机构共同探索更具可持续性的音乐商业模式，并参考韩国音乐市场在专辑商品化、线上专辑及环保材料方面的实践。</p><h2 id="_2-人物-术语-语气风险点" tabindex="-1">2）人物/术语/语气风险点 <a class="header-anchor" href="#_2-人物-术语-语气风险点" aria-label="Permalink to &quot;2）人物/术语/语气风险点&quot;">​</a></h2><ul><li><strong>SKY-HI与日高光启</strong>：统一人物称谓。正文以“SKY-HI”发表观点时，不宜擅自改为“日高光启”；叙述其管理者身份时可结合上下文处理。</li><li><strong>BMSG、BE:FIRST、BESTY、LAPONE ENTERTAINMENT、LDH</strong>：均为专名，首次出现时可保留英文并加中文说明，后文统一写法。</li><li><strong>原盘收入（原盤収入）</strong>：建议译为“母带收入”或“原始录音版权收入”，避免误解为实体唱片销售额。</li><li><strong>法人特典</strong>：不是“法人福利”，应译为“各销售渠道/唱片店专属特典”。</li><li><strong>CD多卖、重复购买、榜单操作（チャートハック）</strong>：需区分“粉丝为收集特典而重复购买”和“为提升榜单排名而进行的策略性消费”。</li><li><strong>记录公司/唱片公司（レコード会社）</strong>：根据语境统一译为“唱片公司”，不要机械译为“记录公司”。</li><li><strong>“白か黒かで過激派になる必要はありません”</strong>：语气是反对简单二元对立和极端化，不宜译得过于激烈或说教。</li><li><strong>“真綿で首を絞める”</strong>：比喻行业被缓慢、持续地拖入困境，可意译为“温水煮青蛙式地持续压缩生存空间”或“慢慢走向窒息”。</li><li><strong>韩国市场数据段落存在明显文本错乱</strong>：<br> “ント応募のため”“25。4%”“52。7%”等内容疑似OCR或排版错误，翻译前应核对原始资料；不能直接按现有字面翻译。</li><li><strong>“CDを同梱しないアルバム”</strong>：应明确为“不附实体CD、通过二维码等方式提供线上试听/收听的专辑形态”，避免译成“没有音乐内容的专辑”。</li><li><strong>CO2、SDGs、MV、QR code</strong>：可保留英文缩写，并在首次出现时补充常用中文。</li><li>整体语气兼具<strong>行业分析的严谨性、创业者的责任意识及艺术工作者的共情与热情</strong>，避免译成激进批判、商业宣传或纯学术评论。</li></ul><h2 id="_3-翻译时建议重点" tabindex="-1">3）翻译时建议重点 <a class="header-anchor" href="#_3-翻译时建议重点" aria-label="Permalink to &quot;3）翻译时建议重点&quot;">​</a></h2><ul><li>保留文章“提出现状问题—说明BMSG具体行动—分析行业反响—比较日韩市场—提出行业协作愿景”的论述结构。</li><li>“我们不是要否定唱片公司，而是希望推动行业转型”是核心立场，翻译时应避免将文章处理成对唱片公司的全面批判。</li><li>对CD、周边、特典、流媒体、实体销售和版权收入等概念进行严格区分，尤其注意“CD卖得多”不等于“BMSG或艺人获得的收入高”。</li><li>第一人称部分应保持自然、坦率、有判断力的口吻；第三人称介绍部分则保持客观克制。</li><li>对“ありがたい”“期待しています”“と思います”等表达适度保留谦逊和开放感，不宜全部强化为确定性结论。</li><li>韩国案例涉及统计数字、调查对象及调查结论，必须先修复原文错乱并核实数字，再进行正式出版翻译。</li><li>“グッズ化”“音楽商材”“法人共通特典”等行业表达应统一术语，避免同一概念在全文中出现多种译法。</li></ul>',6)])])}const m=r(s,[["render",a]]);export{d as __pageData,m as default};
